quests[59202] = { id = 59202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Chosen", description = "Only one rune remains...\n\nWe should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.", completion = "I will have my soldiers honor Krexus as he deserves.", objectives = "Return to the House of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59203] = { id = 59203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Me a Loan", description = "I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. \n\nHowever, a few of those customers are late with their payments. And a customer who does not pay is a customer without value.\n\nPlease ask them to surrender what they owe. I trust you know what to do if they refuse.", progress = "Do not try to cheat me out of anything I am owed. I will know.", completion = "Yes, you are more valuable than I first surmised.", objectives = "Collect 6 Anima Vials from the arena spectators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59206] = { id = 59206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of the Primus", description = "Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it.\n\n<Draka peers at you.>\n\nYou came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right.\n\nTell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones.\n\nIt would be an honor to fight by your side again, {name}.", completion = "I am glad of your return, mortal.\n\nI pray you were successful in preventing the advent of war between Bastion and Maldraxxus.", objectives = "Return to Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59207] = { id = 59207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unshackled Knowledge", description = "These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars.\n\nI fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine.\n\nMost escaped with me, but Lano, Eratus, and Tyrana have not returned yet.", completion = "We've already treated some of the kyrian you freed. Thank you for your aid, {class}.", objectives = "Free Curator Lano, Librarian Eratus, and Historian Tyrana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59209] = { id = 59209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebel Reinforcements", description = "<General Draven looks around.>\n\nWe require additional reinforcements.\n\nI know of two here that are fiercely loyal to the true purpose of Revendreth. The Fearstalker left them here to be consumed by the anima drought due to their allegiance.\n\nThey are both fully capable of assisting us in our mission.\n\nTake this anima stake and infuse them. Direct them to me, I will explain the situation.", progress = "Are our allies infused?", completion = "Our numbers are bolstered. Our survival chance is only slightly less grim.", objectives = "Recruit Watchmaster Boromod and Tactician Sakaa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59210] = { id = 59210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Cores", description = "This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall.\n\nWe will use our knowledge of his secret ritual to lure him out of the House of Rituals. \n\nTake these crystals, {name}. Charge them with anima reclaimed from Mor'Bitan's slain minions.\n\nBut fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun.\n\nThat is when we will strike.", progress = "Is it done?", completion = "Well executed.", objectives = "Fracture the three Depleted Anima Crystals, then charge the Fractured Anima Crystals with deceased Morbid Ritualists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59211] = { id = 59211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Village" }
quests[59223] = { id = 59223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Any Other Name", description = "Excellent work, my apprentice! Our laboratory is back in working order!\n\nNow, there is one final ingredient we require to complete our potion for Margrave Stradama.\n\nYou will need to run along to the greenhouse. I've cultivated a sprig of dreadshade that should be ready to harvest.\n\nI will prepare the other reagents while you're away. Be safe, apprentice!", progress = "Have you found it?", completion = "Come, my apprentice! Our efforts nearly bear fruit!", objectives = "Collect Dreadshade Extract for Marileth's potion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59229] = { id = 59229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantuan Seeker" }
quests[59230] = { id = 59230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartanos, Flayer of Souls" }
quests[59231] = { id = 59231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathomless Power", description = "Forgive me, apprentice... I felt a bit woozy for a moment! But you've done it! You've crafted the potion!\n\nI'm so proud of you. What joy your work brought to our margrave!\n\nWhat manner of teacher would I be were I to ask for your help and not offer my own in return? If you have research you must conduct, you have my full support!\n\nLet us venture to your laboratory, then. I wait with bated breath to behold your future achievements!", completion = "I see you've made a new ally... of a sort. And another rune has been empowered.", objectives = "Meet Marileth at the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59232] = { id = 59232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Humility", description = "Thank you for your service in deposing the Accuser and elevating Lord Chamberlain in her place.\n\nThe Accuser's unprompted betrayal has rendered her both undeserving and unfit to serve on the Court of Harvesters.\n\nNow, please, observe what happens to traitors in Revendreth.", progress = "Please observe silently, Maw Walker.", completion = "I am nothing if not merciful and understanding.\n\nThe Accuser will be given every opportunity to repent her errors and learn from them.", objectives = "Witness the Accuser's judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59233] = { id = 59233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prince's New Crown", description = "The crown is ready. I will entrust you to deliver it to Renathal.\n\nMake haste, {name}. This power will surely attract assailants if word gets out.\n\nYou may use the mirror to return. Know that I will be dispatching others to destroy it after your arrival. \n\nSafe travels, Maw Walker.", completion = "Excellent work, {name}. \n\nWith this crown, I can focus the magic of the Harvesters into an unstoppable force. Now we continue our mission to redeem Revendreth. As a token of my appreciation for all of your help, I open up our armory to you. Please pick your reward.", objectives = "Deliver the Crown of the Harvesters to Prince Renathal in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59234] = { id = 59234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixing A Mess" }
quests[59242] = { id = 59242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their New Home", description = "It pains me to leave my mother behind... but the souls of my people must be brought to safety.\n\nI heard the attendants in Oribos speaking of a place called Ardenweald. A realm of ancient forests where the spirits of nature slumber.\n\nThis is a land you know well, is it not? I would see its wonders with my own eyes.\n\nPerhaps the spirits there will know how to save my minn'do from the Night Warrior's power.", progress = "You've returned. But what of the others?", completion = "My heart aches for Tyrande. The might of the Night Warrior is empowering her to battle these monsters... but it will consume her if we do nothing.\n\nShandris and I will investigate a... promising whisper that I have heard. I shall call upon you when I know more.", objectives = "Take Shandris Feathermoon and the rescued night elf souls to Ysera at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59246] = { id = 59246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", completion = "I will trust you for now, {name}.\n\nBut should you betray me, I will ensure you endure the same torments I do.", objectives = "Find Shandris Feathermoon within Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59254] = { id = 59254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped other members of her expedition.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", completion = "Fine work, {name}. Let's speak with Alaria and hunt down those quilboar.", objectives = "Spar with Captain Garrick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59256] = { id = 59256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fearstalker", description = "The trap has been set and the Fearstalker has walked right in.\n\nJust as I expected, her pride has blinded her to the obvious. Have that vial I gave you earlier ready. It may prove useful in the fight ahead.\n\nWhen you are ready, we can spring the trap.", progress = "The Fearstalker must be defeated.", completion = "This medallion will serve us well. But we lack our leader to don it.\n\nWe must seek out more allies.", objectives = "Speak to the Accuser to trigger the trap, then kill the Fearstalker and collect the Medallion of Dread.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59258] = { id = 59258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home of the Tirnenn", description = "The Horned Hunter is no longer here. But I do know where he went.\n\nHe tracked his prey to the west of here, in the Elder Stand. These woods in particular have grown dangerous as of late, and we are currently beset by invading devourers.\n\nThey have overrun the roads between here and the Stand. I shall accompany you across the bridge, and see that you are delivered to the Horned Hunter.", completion = "Now, let us speak of the hunt.", objectives = "Fight your way into Tirna Scithe and find the Horned Hunter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59259] = { id = 59259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Tormentor" }
quests[59262] = { id = 59262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Wings", description = "You help me? Really? Wow!\n\nLook at me. What am I?\n\nI have beak. Feathers. Scaly toes. I am bird, yes? \n\nBut birds have wings. And I have arms. Why I not have wings? \n\nI broken. I can not fly.\n\nLarion nearby, flies so gracefully. I must study her wings up close! \n\nYou help me?", progress = "If I can study a larion wing, surely I can learn!", completion = "Perfect! I will examine closely.", objectives = "Bring KowalskosAriella's Wing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59263] = { id = 59263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers of Flight", description = "Now, let us see this next to my arm...\n\nLook! There many long feathers along the edges of the Larion's wing!\n\nAnd none on mine. This is why I can not fly!\n\nHmm. It will take lots of flight feathers to give me wings. \n\nYou help?", progress = "Feathers... So many feathers...", completion = "Yes, these are enough feathers to make my arms into wings!", objectives = "Bring Kowalskos 100 Larion Flight Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59265] = { id = 59265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prying Eyes", description = "The Constructs would repurpose the carcass of our necropolis. But we will need its parts for our own ends.\n\nLet us deliver a warning to these scavengers.\n\nSlay the Constructs amid our wreckage. Pluck the eyes from their skulls. Such is our signature.\n\nThey will know to fear the darkness once more.", progress = "You offer gifts?", completion = "I see cowardice in these eyes. You have done well.", objectives = "Collect 20 Betrayer's Eyes from constructs in Akarek's Tears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59291] = { id = 59291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59292] = { id = 59292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59293] = { id = 59293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Formula", description = "You may think I'm naturally gassy, but it actually takes a lot of work to build it all up. This is all the result of a nice coating of Pox Nodules.\n\nHelp me refresh my coating.\n\nJust get me near the absorbing pox and I'll pull the nodules right off his slimy skin.", progress = "Did you get what he needed?", completion = "He's smelly again? We'll at least he's happy, even if we are not.", objectives = "Help Gas Bag collect Pox nodules.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59311] = { id = 59311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Catch a Glimmerfly", description = "Yes! Proper tools collected. Now to catch glimmerflies!\n\nAnima drought more severe in northern pools. Many Starving Glimmerflies, most eager to drink from our animyllis blooms.\n\nPlace blooms, then while glimmerflies are drinking attach to filaments! Then return to me.", progress = "Glimmerflies will surely help me fly!", completion = "<Kowalskos gets very excited> \n\nWow! It worked! I hope they hold me up, too!", objectives = "Capture 5 Starving Glimmerflies in the Shimmering Pools, then return to Kowalskos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59314] = { id = 59314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinfall", description = "I knew you could be counted on. Revendreth's revival relies on forging pacts with those outside of our realm. \n\nThe Prince never had any doubt that you would agree to join our cause. He summoned the Court of Harvesters in anticipation of your arrival. \n\nRenathal awaits you within Sinfall, where you will be presented to the court.", completion = "I never doubted you for a moment, {name}.", objectives = "Report to Prince Renathal in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59315] = { id = 59315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court of Harvesters", description = "Partnerships such as ours will be key to Revendreth's revival. \n\nAs Harvesters, we have the ability to extend our powers to mortals, though the decision must be unanimous. To that extent, the court has gathered and is awaiting your arrival.\n\nLet's not keep them waiting.", progress = "You will be welcomed by the court, I have no doubt, but first, you must swear an oath before the Harvesters.", completion = "Welcome to our humble court, {name}.", objectives = "Stand before the Court of Harvesters and pledge your loyalty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59316] = { id = 59316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Binding Power", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59317] = { id = 59317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthening the Bond", description = "Do you feel it, too? Our connection is stronger than I imagined could be possible. \n\nI have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. \n\nSinfall needs our strength. Perhaps it is best we engage in this method now.", objectives = "Strengthen your bond with Nadjia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59319] = { id = 59319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing Our Efforts", description = "A venthyr's primary responsibility is ensuring that souls are unburdened of their pride, but they must see to other matters as well. \n\nWe must act beyond the bounds of Revendreth to ensure that the souls of the Shadowlands keep to their fate.\n\nAllow me to demonstrate with a simple task for your companion here. This will be the first of many strikes.", progress = "These calculated strikes will further our cause.", completion = "The mission will be a complete success, I have no doubt.", objectives = "Inspect the Command Table and start an adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59321] = { id = 59321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Covenant", description = "Our covenant is more than just pacts and promises. We have immense power, too. And that power we shall bestow upon you in a sacred ritual.\n\nOnce complete, you will be able to call upon our gifts with ease.", completion = "Welcome, I must admit my eagerness to partake in this monumental occasion.", objectives = "Meet Prince Renathal in the ritual hall on the lower level of the sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59322] = { id = 59322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shared Souls", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", sourceObjective = "Meet The Accuser at the Forge of Bonds.", sourceObjectiveStatus = "unverified-source-field" }
quests[59323] = { id = 59323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima Awakening", description = "This ritual will bestow upon you our gift. \n\nWe will stir the anima within your soul, awakening a power that has only been known to Harvesters.   \n\nIt has never been performed on a mortal before, but I have been assured that it won't hurt a bit.", progress = "Take your place when you are ready to begin.", completion = "So long as the pact remains, so shall our power.", objectives = "Participate in the Harvesters's ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59325] = { id = 59325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stalwart Ally", description = "We have our work cut out for us, Maw Walker. The Harvesters will not relinquish their power without a fight. \n\nYou will need stalwart allies at your side. Ones that know how battles are fought within the Shadowlands. \n\nLet me be your guide. Together, we will see Revendreth return to its true purpose.", completion = "Together we are stronger.", objectives = "Complete the soulbind process with General Draven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59327] = { id = 59327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Ruin of Rebellion", description = "Well, here we are -- Sinfall.\n\nLast I saw, the Master was dragging Prince Renathal and his most loyal followers here in a prison convoy. However, this is a forbidden place, wrapped in rumors and mystery. I heard it was once the workshop of Denathrius, where he performed dark experiments.\n\nIntriguing to be sure, but we are here to find Renathal. Search below, but proceed with caution. I will send word for the Accuser to make her way here with what allies she can muster.", progress = "Flesh that walks and talks in the Shadowlands. Interesting.", completion = "I will sever your head from your body should you...\n\nWait...\n\nYou are still alive? That means you are... the Maw Walker?", objectives = "Search Sinfall for any signs of Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59339] = { id = 59339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped the rest of the expedition... including my son.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", completion = "Fine work, {name}. Let's speak with Alaria and hunt down those quilboar.", objectives = "Spar with Captain Garrick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59340] = { id = 59340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallath's Bell" }
quests[59342] = { id = 59342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Wilds", description = "As a hunter, you need a trustworthy beast at your side... or else these quilboar will slaughter you.\n\nWhen you're ready, I'll teach you how to tame such a beast. Then you must find one to be your loyal companion.", progress = "I'll teach you how to tame beasts. Then you'll need to choose any animals nearby to tame.", completion = "You've got a loyal companion by your side. Take good care of them, and they'll take care of you.", objectives = "Learn Tame Beast from Austin Huxworth, then use Tame Beast on any nearby wildlife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59343] = { id = 59343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kindred Spirits", description = "I have come to the realization that you and I are meant to be the most kindred of spirits. \n\nYour enduring nature has enraptured me, and I'm afraid I cannot bear to imagine an afterlife without your beguiling presence. \n\nLet us bind our souls, and forever carry each other in both heart and mind.", completion = "My heart swells, knowing that our souls are bound for all eternity.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59344] = { id = 59344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renavyth's Medallion" }
quests[59345] = { id = 59345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantoriax's Warsword" }
quests[59346] = { id = 59346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indri's Flute" }
quests[59347] = { id = 59347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monk's Focus", description = "You fought well against the harpies, but we all need to become stronger to face what lies ahead.\n\nThe first step is to find a nice place to meditate and focus yourself.\n\nA monk is only as strong as they are focused.\n\nCome. I know of such a place.", progress = "Let us meditate. I find meditation always helps clear my mind.", completion = "There's something different about you, {name}. Let's see exactly what it is.", objectives = "Follow Kee-La and meditate with her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59348] = { id = 59348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Wings!", description = "Idea! Maybe I am too heavy. Maybe need more wings!\n\nGlimmerflies have lovely wings. With correct bait and strong rope, perhaps we can catch.\n\nPlease bring Animyllis Blooms. Their nectar is delicious for glimmerflies, and makes them drowsy!", progress = "Animyllis Bloom nectar is a glimmerfly's favorite sleepytime treat!", completion = "I enjoy these blooms. Such a unique odor, yes?", objectives = "Collect 10 Animyllis Blooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59349] = { id = 59349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Spar", description = "Let us have a quick sparring session before we return to camp, {name}.\n\nI want to see how this island has pushed you to grow.", completion = "I'm glad to hear you and Kee-La sharpened your skills. We're going to need all our strength to push back the ogres.", objectives = "Spar with Kee-La.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59350] = { id = 59350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Druid's Form", description = "Thank you for rescuing me, {name}. Allow me to aid you in your druidic studies.\n\nTo escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same.\n\nCome with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", progress = "Come. The spirits of nature await us.", completion = "Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form.", objectives = "Commune with the nearby druid stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59351] = { id = 59351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strings and Things", description = "Glimmerflies are creatures of anima. Though they look delicate, they are quite strong!\n\nFilaments from etherwym tails are sturdy. They should help hold onto glimmerflies. \n\nCollect for me!", progress = "Etherwyrm Filaments are almost pure anima. Very hard to break!", completion = "<Kowalskos pulls on the filaments with all his might>\n\nSee? Very strong!", objectives = "Collect 10 Etherwyrm Filaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59352] = { id = 59352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mage's Knowledge", description = "Ye got some good spells fer a novice mage. Ye might even be as good as I am one day!\n\nBut ye don't know Polymorph! How could ye not know that?\n\nPolymorph's one of a mage's most useful spells. I can teach it tae ye, if ye can find me spellbook.\n\nLast I saw, the ogres threw me book in the lake. The LAKE!\n\nGo get me book, and I'll show ye how tae cast Polymorph.", progress = "I hope me book isn't too damaged after sittin' at the bottom o' the lake.", completion = "Perfect! Let's see... ah, the page for Polymorph is fine! \n\nWell, it's missin' a few words, but once ye know the magic ye can skip over most o' this.\n\nHere, I'll teach it tae ye... and I'll show ye how it works!", objectives = "Recover Meredy Huntswell's book at the bottom of the nearby lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59354] = { id = 59354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Way to Use Sheep", description = "I'm not gonna send ye off without showin' ye how tae properly use this spell.\n\nYe wanna cast Polymorph if ye get yerself into a situation when two foes are fightin' ye at once. \n\nCole and I will spar with ye a bit tae make sure ye know what tae do.", progress = "And don't ye worry, recruit. Ye won't be turnin' anyone into a sheep permanently!", completion = "I think ye got the hang o' it. Cast Polymorph if ye get yerself in over yer head.", objectives = "Practice using Polymorph against Meredy and Private Cole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59355] = { id = 59355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Trap", description = "By now, most hunters would have been trained in the art of trapping. Allow me to get you up to speed.\n\nWe'll start with a freezing trap. In order to make one, you'll have to forage materials from your surroundings.\n\nMeredy can provide you with a mote of ice. Scavenge the area for the rest of what is required.\n\nAnd don't delay. You will need that freezing trap to deal with a problem that has cropped up within the camp.", progress = "Did you get the supplies needed? Meredy should have the ice mote, while the other two should be nearby.", completion = "With a little work, this can become a trap you can use. \n\nPart of being a {class} means making use of what your surroundings provide.", objectives = "Scavenge parts in the area to create a Freezing Trap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59356] = { id = 59356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Stalker", description = "Now that you have your trap, there's a problem we need to deal with.\n\nA wild beast has been stalking our camp. It's already stolen some of our food. We have little enough as it is.\n\nYou and I will work together. Set your freezing trap and lure out whatever this creature is.\n\nOnce it is caught, I will determine if the beast can be tamed... or if it needs to be put down.", progress = "Use the Freezing Trap anywhere within the Ogre Ruins. Just don't do it right within the camp.", completion = "Thank you for the help, {name}. I have one last lesson to impart--calling a different companion to your side.\n\nThere are plenty of wild beasts on this island. See which ones you can tame.", objectives = "Use your Freezing Trap within the Ogre Ruins to lure out the beast stalking the camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59426] = { id = 59426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Personal Assistant", description = "Here in Hero's Rest, we have a beacon that is the fastest way to draw the Polemarch's attention.\n\nIt has been quite some time since we have used it, and I am afraid that it has fallen into disrepair.\n\nI authorize you to receive a steward companion during your stay here in Bastion.\n\nI will call for some to convene here. You may select one to aid you.", progress = "Stewards are the force that keep Bastion running.", completion = "Whenever you need assistance, your steward will be available to provide many services.", objectives = "Select a steward to aid you, then return to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59427] = { id = 59427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need More Power", description = "Laurent's plan is a bit ambitious. \n\nMirrors are most reliable when used to traverse short distances. Traveling to the sanctuary will require a great deal of power, more than he or I have. \n\nThe shrouded have stores of anima in their compound. With enough of it, the mirror should be stable enough to get us where we need to go.", progress = "Long distance travel requires a great deal of power.", completion = "Yes, this will do.", objectives = "Collect anima from around The Shrouded Asylum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59430] = { id = 59430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague on Your House", description = "Though the physical House of Plagues is lost, the knowledge contained within was not. There are survivors here that continue to research and develop new horrifying weapons. \n\nIn time we will restore the house and rise to even greater power, unleashing creations and plagues never before seen upon our enemies!\n\nPerhaps you can help? Speak with survivors and see if any of them can use your aid.", progress = "Have you spoken to anyone?", completion = "Working together will benefit both of us greatly!", objectives = "Speak with House of Plagues survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59441] = { id = 59441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulsmith Yol-Mattar" }
quests[59520] = { id = 59520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plaguefall: Knee Deep In It", description = "There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes!\n\nThese dangers still remain and spread out from the ruins, infecting new victims daily.\n\nI need you to travel into the ruins and recover samples from the victims there.", progress = "Have you brought me the Poxedskin Samples?", completion = "Working together will benefit both of us greatly!", objectives = "Enter Plaguefall and recover 12 Poxedskin Samples and Margrave Stradama's Plasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59554] = { id = 59554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fine Journey", description = "Aspirants new and ancient, take note! The heralded Agthia's Repose calls.\n\nMake the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm!\n\nFind the Repose just a short ride southwest of Hero's Rest.", completion = "What brings you to our humble grounds?", objectives = "Speak to Keeper Mnemis in Agthia's Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59555] = { id = 59555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy at the Door", description = "The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever.\n\nOur reserves have met the enemy in battle. I need you to break the siege.\n\nReport to Heirmir and Marileth. They will give you the means to rain destruction on our foes.", completion = "The enemy is licking their wounds! Our troops will hold the line for now, but we should be prepared for more assaults.", objectives = "Ride Ragewing and destroy the enemy forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59556] = { id = 59556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome To Our House", description = "Your ties to the other covenants had me doubting you would return. I see now that was foolish of me.\n\nOutsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride.\n\nOne day, he might return as well. But we cannot afford to wait. \n\nIn the Primus's absence, I will name you a Necrolord of Maldraxxus.", progress = "There is no greater honor than to defend the Shadowlands as a Necrolord of Maldraxxus.", completion = "This is our war to win, Maw Walker. It is now yours, as well.", objectives = "Speak with Baroness Draka to be inducted as a Necrolord in the Maldraxxus covenant hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59578] = { id = 59578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Get Ready to Humble" }
quests[59581] = { id = 59581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Sinfall" }
quests[59583] = { id = 59583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Stormwind", description = "Now that we are back in Stormwind, I need to deliver my mission report to King Wrynn.\n\nIn the meantime, I've asked Lindie to accompany you around the city. There's a lot to see and do in Stormwind, so feel free to explore at your leisure.\n\nI'll send for you once I've delivered my report to the king.", completion = "Hey, {name}! It's good to see you!\n\nCaptain Garrick asked me to show you around the city. I'm so excited!", objectives = "Meet with Lindie Springstock at the city gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59585] = { id = 59585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We'll Make an Aspirant Out of You" }
quests[59586] = { id = 59586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Dalgrun Steelpine to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside.", objectives = "Speak with Dalgrun Steelpine to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
