quests[59594] = { id = 59594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Kualiang Thunderfist to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside.", objectives = "Speak with Kualiang Thunderfist to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59596] = { id = 59596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collective Soul", description = "Souls in Maldraxxus are bound together in war. We draw strength and wisdom from those around us.\n\nShould you fall in battle, part of you would remain with your fellow soldiers. Just as they would remain with you. \n\nPlague Deviser Marileth has volunteered to teach you the process of soulbinding. From what I have seen, yours will be a powerful bond.", completion = "I'm so pleased to see you again, my apprentice!", objectives = "Speak with Plague Deviser Marileth about the soulbinding process.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59597] = { id = 59597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come On, We're Simpatico!", description = "Soulbinding is a wondrous process! I invite you to bind with me to learn how it works, but in time you might bind with others. \n\nI have known many soulbinds, but the foremost of them all was Margrave Stradama! Her knowledge, talent and kindness became part of who I am. Now and forever, it is a bond we share.\n\nI only hope to be so useful to you, my apprentice! Bound together, I shall grant you all I can and aid you even when we are apart.", completion = "Our shared knowledge will benefit all of Maldraxxus.", objectives = "Complete the soulbinding ritual with Plague Deviser Marileth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59598] = { id = 59598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good for the Soul", description = "Two souls are better than one! We can achieve far greater things together than we can if we were alone.\n\nHowever, it is not just the two of us against all threats. There are many more that will aid us in the coming battles.\n\nLet's speak with Merick to learn more on the subject. Don't be shy--I can introduce you!", sourceObjective = "Speak with Merick.", sourceObjectiveStatus = "unverified-source-field" }
quests[59599] = { id = 59599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaining the Court" }
quests[59600] = { id = 59600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotbriar Trouble" }
quests[59601] = { id = 59601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Vestibule" }
quests[59603] = { id = 59603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Shadowlands Service", description = "As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. \n\nWhen enemies emerge, we are the ones who face them!\n\nThe threats to the Shadowlands are far more than any one of us can handle. That's where I come in.\n\nI will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.", progress = "An easy task to complete.", completion = "And so, it is as if you had led the battle personally! Impressive work, if I do say so myself.", objectives = "Use the Command Table to send Marileth on an adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59604] = { id = 59604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takin' Down the Beast" }
quests[59605] = { id = 59605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takin' Down the Beast" }
quests[59607] = { id = 59607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takin' Down the Beast", progress = "Bad bat gon' get smashed! Need ammo! Ammo in Dredhollow!", completion = "Haha! Smash time!" }
quests[59609] = { id = 59609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For the Dead", description = "Excellent work, my apprentice! You have completed your training and are now a true Necrolord.\n\nThat also means you've taken on additional responsibilities. Such is the burden of genius!\n\nI believe Baroness Draka wanted to have a word with you.", completion = "I hope you're settled--there's no rest for the weary in Maldraxxus.", objectives = "Report to Baroness Draka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59615] = { id = 59615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Dog Has Its Day", description = "Maw Walker, when I heard you were building constructs and a home for souls still loyal to Maldraxxus, I began my search for you!\n\nI am loyal and have always wanted a construct form, but the Margrave was unwilling to build one that suited my natural inclinations.  \n\nI lived my whole life with the curse, it's all I know, and it's all I still want.\n\nWould you build a construct for me?", progress = "Are you willing to do this?", completion = "I know this soul, she is strong and very loyal. We would be well aided by building this most unusual construct.", objectives = "Take specifications for Neena's construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59616] = { id = 59616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of One", description = "Mevix will lead the attack, but you will finish it. There are no reinforcements, no cavalry.\n\nOnly you and your runeblade.\n\nShow me the might you wield, outsider. Lay siege to the House of Constructs and bring them to ruin!", completion = "Your voice... you are not one of the Maldraxxi?", objectives = "Meet Secutor Mevix near the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59617] = { id = 59617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Fiend Saboteurs" }
quests[59621] = { id = 59621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking a Few Eggs", description = "As you can see, we have a gorm problem.\n\nI'm not sure what has them so riled up. They've been getting bigger, more hostile. It must be due to the anima drought. If nothing stops them, they'll eat everything!\n\nTheir egg production is out of control. We can't let their population grow any larger. Please, go in to their nests and destroy as many of their eggs as you can find.", completion = "This should hopefully curtail their numbers. Thank you for your help.", objectives = "Destroy 10 Gorm Eggs in the Banks of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59622] = { id = 59622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending to the Tenders", description = "The eggs are a problem, but so are the gorm that take care of them.\n\nThe egg-tenders are the leaders of the hive when no matriarch is present. If left unchecked, they will simply produce more eggs and we will be right back where we started. Or worse, one of them could turn into a queen. \n\nThey are simply too large and hostile for us to properly contain. I see no other recourse than to put them down.", completion = "The population will produce more tenders eventually. You have bought us valuable time.", objectives = "Slay Egg-Tenders Tiom, Bloome and Erys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59623] = { id = 59623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What a Buzzkill", description = "What do you say? Fancy one more hunt?\n\nOne of those little flying pests has grown into a very large flying pest. Large, pristine gorm parts are hard to find in the best of times, and a smith always appreciates a challenge.\n\n<Cavina's voice drops as he leans in towards you.> Besides, I'm worried about the safety of my family and the rest of us in the grove.\n\nBring me the stinger from that big fella and I'll make it worth your while.\n\nDo we have a deal?", progress = "I must say, I am looking forward to the opportunity to working with such a fine specimen.", completion = "Yeah, this is good gorm right here. I'll make you something special from it.", objectives = "Deliver Buzzkill's Stinger to Gormsmith Cavina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59625] = { id = 59625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Cure", completion = "Your arrival is expected. We await results.", objectives = "Meet with the Paragon of Courage in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59641] = { id = 59641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nation of Kul Tiras", description = "Kul Tiras is the greatest naval power on Azeroth, and a former member of the Alliance. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was killed at Theramore.\n\nMany have said that Jaina believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father on that day. Perhaps she feels it is time to put the past to rest.\n\nLoathe as I am to put Jaina at risk... Kul Tiras must rejoin the Alliance.\n\nLight be with you.", completion = "Home again, after all this time.", objectives = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59642] = { id = 59642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling Hairs", description = "The abominations are well organized and well supplied. We've not been able to gain any ground.\n\nA little disorganization in their supplies and reinforcements might give us an edge.\n\nI need you to work you way behind their lines and eliminate three abominations handling their supplies.", objectives = "Eliminate Strategist Orco, Lobber Jalrax, and Munitioner Vizic", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59643] = { id = 59643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Race Day in the Ramparts!" }
quests[59644] = { id = 59644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinded By The Light", progress = "Hopefully you did not get too scorched out there.", completion = "That should buy us some time and carve us a bit of a path. Now to take advantage of the situation.", objectives = "Use the mirrors atop Sinfall to seal the gates of Castle Nathria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59645] = { id = 59645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Rains", progress = "See justice done.", completion = "Our will is done.", objectives = "Slay 30 enemy forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59648] = { id = 59648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace by Piece", description = "These Maldraxxi fiends have reoccupied my temple. They have entrenched this resurgence with shields powered by necromancy.\n\nMy disciples--the ones who were not captured and executed by your treacherous compatriots--report the core of a necrotic bulwark to the south. We cannot counter their forces until the shield is brought down.\n\nSee it done. I will not tolerate your presence otherwise.", progress = "Do not keep me waiting.", completion = "We have only just begun.", objectives = "Disable the Necrotic Bulwark in the South.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59650] = { id = 59650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Hesitation, No Surrender", description = "I cannot fathom where the constructs acquired these reinforcements, but we are once again outnumbered. I seethe at the thought of my fallen disciples.\n\nYou will make this right.\n\nThe renegades have established a foothold in the northern region of the temple. Their necrotic magic has granted them a shield, defending them from ranged assault. Disable it.\n\nLet nothing impede you. This is the way of Courage.", completion = "This will begin to set things right.", objectives = "Disable the Northern Bulwark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59653] = { id = 59653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Cross Courage", description = "We have rendered the enemy holdouts defenseless. My disciples will begin preparations to purge the corruption that your errant kind have left on our home.\n\nBut more still remain in the inner sanctum of the temple. Their defenses prevent us from flying in en masse, but I can secure a foothold myself. We will cross the breach and annihilate them.", progress = "We shall not waste time.", completion = "This is as close as I can take you. Make it count.", objectives = "Cross the breach with Xandria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59656] = { id = 59656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well, Tell the Lady", description = "<Thorodir breathes a deep sigh of relief.>\n\nThat's that, I'd say. The Banks are largely safe now, thanks to you. We can handle the rest of the cleanup on our own now.\n\nThe Lady of the Falls will want to hear of your success here. Why not go tell her the good news?", completion = "Ah, that is wonderful news. Thank you for your assistance.", objectives = "Report to the Lady of the Falls in Glitterfall Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59658] = { id = 59658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Express Dominance" }
quests[59659] = { id = 59659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Absolution", description = "My kyrian would have attempted to retaliate by now, but these vile interlopers are a devious sort.\n\nTheir necromancers pollute the air, tainting it with foul power that corrodes our very wings.\n\nI cannot advance an assault until they are eradicated. Deal with these befoulers, and I will deliver retribution to the rest.", completion = "Now we are ready.", objectives = "Slay the three befoulers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59660] = { id = 59660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Court", completion = "This court isn't going to throw itself. Let's get to work!", objectives = "Recruit the personnel needed to open the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59661] = { id = 59661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court Rehearsal", completion = "That went surprisingly well, all things considered. You and I have a real knack for this party-planning stuff.\n\nWe're ready to prepare our first real Ember Court!", objectives = "Help Temel host the rehearsal for the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59674] = { id = 59674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Rivalry", description = "Ah, a fresh soul! Your perspective may prove useful to us.\n\nNemea and I have opposing viewpoints. She lauds her larion, creatures native to Bastion whom she raises and trains as her companions.\n\nHowever, I find that phalynx are the superior beings. They are efficient, obedient, and easy to work with.\n\nPlease, come learn both of our ways. Perhaps you can decide which of our ways of life is superior.", completion = "I am honored that you came to me first. Allow me to show you my ways.", objectives = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59676] = { id = 59676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvester of Desire", description = "So, here's the sketch: we muck you up to look like one of the servants. This stuff is protected by anti-theft so if 'em clothes think they are being stolen they teleport back here, you an' all.\n\nYou \"should\" be able to reach the Countess with your message. Just smile, nod, do as you're told, don't talk to anyone, and don't make eye contact with anything that's got wings. They'll know you shouldn't be there.", progress = "Still got your head at least. They often try to take that first if they are mad at ya.", completion = "Ah, the Countess. Mistress of the court. Always assume she is never alone, and always capable of great treachery.\n\nMmm... treachery...", objectives = "Infiltrate the Eternal Terrace and deliver Prince Renathal's message to the Countess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59678] = { id = 59678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sustain, In Vain", description = "These turncoats have kept busy. They've opened more portals around the area, allowing themselves to replenish their numbers with little trouble.\n\nEven with her might, the Paragon cannot eliminate an endless army. Let us destroy these portals. Without reinforcements to sustain this contingent, it will surely fall.", progress = "The time for mercy is behind us.", completion = "No longer can they sustain themselves. Good work.", objectives = "Disable 6 Necrotic Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59680] = { id = 59680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vesiphone's Vicious Vesper" }
quests[59698] = { id = 59698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wipe the Slate Clean", description = "At last, the skies belong to us once more... and in those skies, the storm of our vengeance brews.\n\nCome, you who claim to be true Maldraxxi. You wish to right the wrongs of those you once called allies?\n\nRain your justice upon them! Show no quarter!", completion = "For Courage!", objectives = "Fly with Xandria and slay Maldraxxi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59700] = { id = 59700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Labor", description = "The evil that threatens Bastion crumbles beneath us. But if we allow this cruel baroness to evade justice, we have not won this day.\n\nShe cowers in the necropolis above, casting her shadow on this once sacred temple.\n\nWe will pull the dagger from our backs. This wound will heal.", progress = "This is all that remains.", completion = "May her memory fade from this place.", objectives = "Slay Baroness Antolyte.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59701] = { id = 59701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Common Ground", description = "Now that we have a stronghold from which to operate, we need to begin the next stage of my plan to wrest control of Revendreth from the Master.\n\nWe must convince the Court of Harvesters to convene. We must not have them come here, though. It would be suicide.\n\nGo to my old fortress, Darkwall Tower, and place these banners at the four most distant points of the tower. This will ensure the power of the Harvesters and the Master will not be able to interfere with a neutral meeting.", completion = "They may look like simple banners, but with the right words and a few appropriate spells, they turn this place into a temporary sanctuary.", objectives = "Place four of Renathal's Banners at Darkwall Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59703] = { id = 59703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abombing Run" }
quests[59705] = { id = 59705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Remembered" }
quests[59706] = { id = 59706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation for the Countess", description = "The Countess, Harvester of Desire.\n\nHer wits are sharper than most swords. While I have never seen her carry a weapon, you must assume she is never unprotected.\n\nHer mansion mirrors my own, on the Northeastern side of Castle Nathria. Her dominion was that of the Castle Ward, and it is her authority that keeps the nobles in line.\n\nShe will appreciate a secret message. I will send a dredger ahead with a plan to infiltrate her party. Meet him on the Bridge of Temptation. Good luck.", completion = "Glad you got here before 'em patrols. I ain't got a permit to park here.", objectives = "Find Cudgelface on the Bridge of Temptation leading to the Eternal Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59707] = { id = 59707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation for the Tithelord", description = "The Tithelord is a bully and a coward, just like every Harvester of Envy before him.\n\nHe is still a force beyond our current reckoning. I have sent Nadjia and Temel to Pridefall Hamlet in the south to ascertain the best, most non-lethal way to reach the Tithelord.\n\nMeet them there and use caution. The Tithelord would kill you in less than the blink of an eye if he thought it would gain him more power or authority.", completion = "Ready to fall with grace?", objectives = "Speak with Nadjia the Mistblade at Pridefall Hamlet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59708] = { id = 59708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation for the Stonewright", description = "The Medallion of Wrath is in the hands of the Stonewright. She is ancient, powerful, and responsible for creating the Stone Legion.\n\nShe is not someone to be subtle with. It is a very dangerous thing to ask, but would you meet with General Draven at the Dominance Gate? \n\nIf we are to see the Stonewright attend, she must know the severity of our request, which means both you and Draven walking right in the front door.", completion = "This will not be an easy day.", objectives = "Speak with General Draven at the Dominance Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59709] = { id = 59709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Afterlife Goes On", description = "A new dawn shines on Bastion. I had my reservations, but you have proven that honor yet remains in Maldraxxus.\n\nTake my hand once more. I will return you to the temple's entrance.\n\nLet all Maldraxxi know of our victory. And for the sake of peace, ensure that this never happens again.", completion = "May our paths cross again.", objectives = "Fly with Xandria to the entrance of the Temple of Courage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59710] = { id = 59710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Invitation", description = "Psst. You there. Yeah, you.\n\nYou that Maw Walker them fangs been going on about? Huh. I figured you'd be bigger.\n\nAnyway, the Taskmaster wants to ahhh ... \"extend his compliments and an invitation to visit his workings.\" That's a fancy word for a bunch of rocks me and my mates are diggin' up.\n\nIf you're keen an' all that, pop down to Feeder's Thicket and meet with the fang's courier, Araak. He'll get you sorted right out.", progress = "The Taskmaster don't like waiting.", completion = "Well, looks like the master just left. What timing.", objectives = "Meet with Courier Araak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59711] = { id = 59711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvester of Envy", description = "Thank you for meeting us at a minimum safe distance from the Caretaker's Manor. There are enough people around here that may still find the idea of me in a cage to be worth the trouble.\n\nIt is too dangerous for you or I to speak to the Tithelord. He is too impulsive and eager to please Denathrius. I recommend we send Temel. \n\nThe stone fiend is a common messenger for Revendreth and few aside from a handful of observers will bat an eye at his arrival. Just shove him when you are ready.", completion = "The Tithelord. I believe he is the two hundred and seventy fifth Caretaker to lord over the Village Ward. \n\nHe is as dangerously ambitious as every Harvester of Envy before him, and will help only if he believes he stands to gain more power.", objectives = "Guide Temel through the Caretaker's Manor and deliver Prince Renathal's message to the Tithelord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59712] = { id = 59712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lay of the Land", description = "So, yeah, not sure why he wants you. Based on a long time working for him, I'm gonna say he wants to use you to do something unsavory to further his interests. But, I'm biased. I could tell you so many stories.\n\nLet's go check on my friend, Nadjia.", progress = "Have you found Taskmaster Matyas's journal yet?", completion = "Appreciate you helping my friend. Keep this up and I'll be in your debt.", objectives = "Check on Nadjia and investigate Taskmaster Matyas's camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59713] = { id = 59713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Active Ingredients", description = "Matyas will be difficult to handle until we can take my sinstone from him. We need something to knock him out. \n\nWill you fetch a few ingredients for me, mortal? I have a cunning plan.", progress = "Do you have the ingredients?", completion = "This should be enough to knock him out for long enough to take my sinstone.", objectives = "Gather ingredients for Nadjia's mixture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59714] = { id = 59714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fine Vintage", description = "We will need something special to use as the base of our mixture. To get him to drink it down he will have to believe you've brought him a gift. \n\nHe fancies himself quite the connoisseur. Some ancient and stuffy vintage will tempt him.\n\nCheck the old cellar near the ruins. It once held supplies. Perhaps a bottle still lingers in the depths. Araak and I will work out the other details.", progress = "Have you found a suitable beverage?", completion = "Ah, that's perfect. He will not be able to resist this.", objectives = "Bring Nadjia a fancy beverage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59715] = { id = 59715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message for Matyas", description = "Alright. Everything is prepared. When you are ready, ask Courier Araak to summon Taskmaster Matyas as though you have just arrived.\n\nI am sure a gift of a favorite drink will tempt him and the poison we've concocted will incapacitate him long enough to take my sinstone from him.\n\nOur plan will work flawlessly!", completion = "Ah, the Maw Walker! I have heard so much about you.", objectives = "Summon Taskmaster Matyas back to camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59716] = { id = 59716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comfortably Numb", description = "A mortal in Revendreth. It's rumored that you can traverse the Maw? Astonishing. I have so many questions.\n\nBut, I must restrain my curiosity. I have a ... shall we say ... proposition for you that I feel would be advantageous for us both. If it is true that you are able to freely travel these lands then you have access to certain information I cannot reach. \n\nYou see how you could be useful to me? Come, let us discuss the matter further.", progress = "My sinstone, please.", completion = "Oh, well done! I had a moment there when you drank the poison that I feared for you. But you're a hearty sort.", objectives = "Poison the Taskmaster to get Nadjia's sinstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59717] = { id = 59717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Remembered" }
quests[59718] = { id = 59718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parasol Peril" }
quests[59719] = { id = 59719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court", description = "Well, we have quorum. You have done all you can do for us at this stage, Maw Walker.\n\nIt falls to me, now, to convince these ancient fools to forsake the greatest patron in all of their reality and throw their lot in with me, a failed rebel with a \"new\" plan.\n\nLet us see if I can still sway a crowd, as it were. Wish me luck.", completion = "Well, that could have gone better. I did not expect them to come around right away, but I had hoped at least one or two of them might.\n\nNow we must do it the hard way. We should leave before they send forces to re-capture this tower.", objectives = "Witness the Court of Harvesters gathering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59720] = { id = 59720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvester of Wrath", description = "We walk in the winged shadows of my brothers and sisters in arms, Stoneborn I have trained since they were first carved from stone.\n\nThis is an ancient rite. If we cross this bridge on foot, defeating any who would dare stop us, we may have an audience with the mother of the stoneborn. However, know that our safe return is not guaranteed, so try not to offend her.\n\nI do not look forward to this.", completion = "I remember when the first stoneborn moved with the breath of anima infused by the Stonewright. \n\nNever, ever, confuse her sympathy for her creations as a weakness. She holds the Medallion of Wrath for a reason.", objectives = "Cross the Bridge of Defiance on foot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59721] = { id = 59721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming the Hunt", description = "<Reldorn grins at you.>\n\nHe knew you'd be back! The Horned Hunter went on ahead to prepare the hunting ground. He said you should join him as soon as you can. \n\nNow that you have the materials for the trap, you just need to reach him...\n\nIt's dangerous territory to traverse, but I've been devising a glamour that should help you avoid the attention of the roaming beasts. Maybe if it's useful, you could put in a good word for...\n\nAhem. Anyway, we should focus on your quarry. Good hunting, friend.", completion = "You are just in time. My preparations are nearly complete.", objectives = "Find Huln Highmountain within the Elder Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59722] = { id = 59722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Necropolis", description = "The necropolis is safe and secure, but we can only maintain a portal to the Seat of the Primus for a short time.\n\nKhaliiq will return with you and work on establishing a permanent portal connection.", completion = "It's like we were never gone.", objectives = "Use the portal to meet Khaliiq in the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59724] = { id = 59724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Honor", description = "Thanks to you, {name}, I am free of Matyas's control for the first time in ... well, a very long time. \n\nNow, together, we will seek my vengeance. \n\nI've laid a solemn duty upon you by naming you as my second for this duel. I know not the code in your homelands but in mine, it is your task to secure the field. Matyas and his followers are garrisoned at Witherfall Ruin nearby. Unless I miss my guess, that's where he will have run.\n\nI will prepare for the battle and join you soon.", completion = "Well, he's certainly chosen a scenic location for a fight.", objectives = "Clear Taskmaster Matyas's followers from Witherfall Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59725] = { id = 59725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivist on the Edge", description = "If the curse isn't removed, Qadarin will waste away until nothing is left! \n\nWe used to bind and seal curses just like this all the time, but we haven't had to deal with one in ages. \n\nGo to Archivist Dreyden at the Grove of Memory. He will know which curse this is and can give you its scroll. \n\nBring it back so we can figure out what we need in order to cast a counter-curse.\n\nHurry, {name}!", completion = "Please tell me you are here to help with the spriggan problem!", objectives = "Speak with Archivist Dreyden at the Grove of Memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59726] = { id = 59726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Trap", description = "At last, I will have my vengeance!\n\nI am certain Matyas will flee again if he sees me first so you will need to confront him on my behalf, friend. Then, while he's distracted, I will engage him.\n\nAt that point, your obligation as my second is a formality. You must assure Matyas does not dishonor the duel and cheat. When he inevitably does, I expect you'll help me defeat him.\n\nHe's just through the portcullis there.", progress = "Matyas will apologize, or he will die.", completion = "I would have allowed an apology, but he chose treachery and has paid the price.", objectives = "Approach Matyas to start the duel. Assist Nadjia when Matyas cheats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59731] = { id = 59731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Expected Guest", description = "While we await word from Huln, another matter of importance has arisen.\n\nBwonsamdi has returned to Ardenweald. Lord Herne believes he is here to request an audience with the Winter Queen.\n\nThe loa of death, however, pursues a different purpose. One that I have glimpsed in my dreams.\n\nMeet with Bwonsamdi. Discover what fate has in store for the both of you.", completion = "Ol' Bwonsamdi knew ya gonna come see me. I got someting ya wanna hear...", objectives = "Meet Bwonsamdi in the Heart of the Forest within Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59732] = { id = 59732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Extra for the Winter Queen", description = "Ya did good wit' how ya handled Mueh'zala. Me be wantin' ta return da favor. We be friends, after all... riiiight?\n\nDat nasty loa be at me mercy now. Him been mutterin' about some tings he stole from ya Winter Queen. \n\nCome along ta me Necropolis. Ya can see what Ol' Bwonsamdi be talkin' about for yaself.\n\nYa gonna come back with someting nice for her majesty... reeeeeal nice.", completion = "While ya be here, why not help clean up some of da trash outside me Necropolis? For old time's sake, eh?\n\nDen we can be dealin' wit Mueh'zala.", objectives = "Travel with Bwonsamdi to the Necropolis in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59739] = { id = 59739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Problem with Containing a Death Loa", description = "Me know Mueh'zala still be hidin' someting. Ol' Bwonsamdi gonna find out what dat be.\n\nBut dis old loa's presence be drawin' all da undead in Nazmir ta me doorstep!\n\nMe be needin' some time ta get Mueh'zala talkin'. \n\nDere be a troll, Zel'han, leadin' da undead. Kill him and show Mueh'zala him broken armor.\n\nDat should end any hope he be havin' of escapin'.", progress = "Zel'han be marchin' in here wit ya head. Me gonna enjoy seein' ya soul tortured in da Maw.", completion = "Me got plans older dan you, {race}. Slaying Zel'han mean noting ta me... ya understand?", objectives = "Kill Zel'han the Betrayer and recover his armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59740] = { id = 59740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repair and Restore", description = "You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead.\n\nIt's quite easy once you've found the fragments, but there are a few things of note to keep in mind. \n\nRepaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. \n\nHere's a few shards to get you started. \n\nRestore the mirror to working order and see where it leads.", progress = "I have complete faith in your abilities.", completion = "You found a boon? Well done! One never truly knows what awaits beyond the mirror.", objectives = "Repair the Broken Mirror and reap the rewards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59741] = { id = 59741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Mojo for a Dark Loa", description = "How many times must de Necropolis come under attack? I suppose no one ever said worshipping Bwonsamdi would be easy...\n\nBwonsamdi seeks to force Mueh'zala into revealing his secrets, and I must do my part to help.\n\nDe undead swarming de Necropolis are animated by Mueh'zala's dark mojo. \n\nBwonsamdi needs some of dat mojo to finish his ritual. Strike down de undead and claim it.", progress = "You got me dat mojo? I be usin' it ta control Mueh'zala durin' me ritual.", completion = "Look at all dis mojo! Dis be just what me need ta make little Mueh'zala talk.\n\nDon't ya be worryin' about da other undead out dere. Ol' Bwonsamdi got a plan for dem.", objectives = "Recover 100 Dark Mojo from undead attacking the Necropolis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59742] = { id = 59742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delaying the Other Side", description = "Many of Bwonsamdi's worshippers did not make it inside when de undead began swarming de Necropolis.\n\nWe need a few more of dem to complete Bwonsamdi's ritual to uncover Mueh'zala's plans.\n\nTake dis powder and throw it on de worshippers who are stuck outside. It should dispel de dark magic dat afflicts dem.\n\nAs for de ones who are already dead... dey will serve Bwonsamdi beyond de grave. Dat is all we could ever ask for.", completion = "Ah good, ya got me all da livin' souls I be needin'.\n\nDon't ya be worryin' about da ones who passed on. Ol' Bwonsamdi not lettin' dem go to da Maw.", objectives = "Use Strange Powder on 6 Injured Bwonsamdi Worshippers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59743] = { id = 59743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spider on the Wall" }
quests[59747] = { id = 59747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Soul", description = "Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia.\n\nShe was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her.\n\nPlease end her misery.", progress = "Have you completed this task?", completion = "I sense that her suffering has ended.", objectives = "Bacilia the Lost slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59748] = { id = 59748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Peace In Death", description = "{name}. I have a favor to ask, if I may.\n\nThis realm... The sense of honor and purpose that guides its denizens calls to me. \n\nMy life was defined by such values. Maldraxxus, for a time, shared them with me... But I returned from the Maw to a land rife with treachery.\n\nI'd like to speak with the Paragon about Bastion.", completion = "Come. There is much to show you.", objectives = "Talk to the Paragon of Courage with Alexandros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59749] = { id = 59749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Little Whisper", description = "Here be da deal, {name}. To get  Mueh'zala talkin', we gotta feed him a teeny bit a da life essence of everybody in dis room.\n\nWhy ya be lookin' at me like dat? When has ol' Bwonsamdi ever let ya down?\n\nMe gonna use da mojo ya got to pull da truth outta him while he be feedin'.\n\nOh, uh, just two more tings. First, I need ya to be ringin' an invitation to a special... friend.\n\nDen I be giving ya more of me mojo powder. Use it during da ritual if any o' me followers be gettin' too weak.", progress = "I be eager to hear what ol' Mueh'zala be have ta say...", completion = "Dere be one loa o' death, {name}. And it be ol' Bwonsamdi. \n\nYa best not forget dat.", objectives = "Ring the gong to summon the special guest, then use mojo powder in the ritual to fuel Mueh'zala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59750] = { id = 59750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Get a Head", description = "An eager rookie who wants to be champion of the arena? People love a story like yours, but the first step is to get you noticed. \n\nHere's the plan. Marcel Mullby needs bloodtusk skulls, but it takes a real fighter to get those!\n\nYou go kill some bloodtusks, use my knife to collect their heads, and deliver them to Mullby. That should get you recognition.", progress = "You deliver those skulls?", completion = "Good work, you're getting some recognition. I hear people talking about how you killed all those bloodtusks!", objectives = "Collect 12 Bloodtusk Skulls and deliver them to Marcel Mullby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59751] = { id = 59751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Shattered Sky", description = "When Sylvanas shattered the Helm of Domination, she was touched by the power it released.\n\nI can sense the echoes of that power, and I know where she has gone.\n\nIf you wish to rescue your leaders, the shattered helm can open a path. It cannot bring you back, however. That you must do on your own.\n\nThe risk is great, {name}, but there is no other way. We will begin the ritual at once.", completion = "Not the most ideal of arrivals, but at least we are still in one piece.\n\nI have not seen any sign of Tyrande. Either she landed elsewhere or continued on without us. We should keep an eye out.", objectives = "Complete the ritual at the Frozen Throne to open the rift into the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59752] = { id = 59752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fractured Blade", description = "The chaotic energies of this place have scattered the Ebon Blade. \n\nI don't think Azeroth's blessings will reach you here, {class}. We will need allies if we are to survive this place.\n\nWe should find them quickly, before they are overcome.", progress = "We have no time for chatter. Let's find those knights!", completion = "We've been in this place mere moments and already our forces are depleted. It will have to do.\n\nTake this horn. It can be used to call upon the remaining Ebon Blade forces to rally against your foes.", objectives = "Rally 10 Knights of the Ebon Blade in the Crucible of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59753] = { id = 59753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruiner's End", description = "One of the... larger fiends... has several of our knights engaged...\n\nHurry to their aid... lest we lose more of our dwindling forces.\n\nGo... it is too late for me...", progress = "Our allies fall as you stand idle.", completion = "I am loath to leave some of our knights behind, but it is obvious we cannot stand against such foes. \n\nWe must make sure their sacrifices are not in vain.", objectives = "Defeat Ruiner Maroth in the Crucible of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59754] = { id = 59754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Blackened Wings", description = "It's a relief to see friendly faces again. But we have little time for pleasantries.\n\nThrall is wounded, and we are being hunted by the denizens of this realm. We must seek shelter at once.\n\nCome, I believe I know of a place.", progress = "What are you doing? This is no time for talk!", completion = "Those images will keep our foes distracted for a time, but they will not give up their pursuit so easily.\n\nWe must make haste!", objectives = "Assist Jaina in escaping the Mawsworn in Calcis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59755] = { id = 59755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flight from Darkness", description = "There's a cave not far from here. If we hurry, we can seek refuge.\n\nThose fiends will give chase if they spot us. Be prepared for a fight!", progress = "This way!", completion = "Rest here while you can, {name}.\n\nI will tell you what I know.", objectives = "Escort the assembled forces from Calcis to Forlorn Respite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59756] = { id = 59756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Moment's Respite", description = "Anduin insisted that our allies would come for us. I confess I had begun to doubt him.\n\nI'm sure you have many questions. I'll do what I can to provide answers, but I'm afraid even after... \n\nWhat has it been... weeks? Longer? Time loses all meaning in a place of such darkness.\n\nForgive me. Let me tell you what little I can.", progress = "I will tell you what I can.", completion = "I need time to recover after that battle. Thrall could use rest, too.\n\nWhile we rest, perhaps you and Mograine can seek answers.", objectives = "Speak with Jaina in Forlorn Respite to learn what she knows about the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59757] = { id = 59757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Seance", description = "If these souls have information we need, we will take it from them.\n\nEven after being shattered by the Banshee, the helm fragment given to you by Bolvar holds the power of Domination. With it, we should be able to take control of the spirits long enough to find out what they know.\n\nThey will need to be sufficiently weakened before we can break them. I'm confident you're more than capable of that task.", progress = "Do you wish to speak to me, or to the dead?", completion = "Useless! These souls are far too fragmented to provide us with anything.\n\nWait... what is that?", objectives = "Use the Shattered Helm of Domination to command 5 Malice Shadows in the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59758] = { id = 59758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking to the Dead", description = "Look over to the ridge. There lies our quarry!\n\nNo telling how many souls are writhing together within that amalgam. With any luck, one of them might be coherent enough to give us answers.", progress = "What are you waiting for?", completion = "Find enough mouths and one of them is bound to speak. \n\nLet's bring this thing back to the cave and find out what it knows.", objectives = "Use the Shattered Helm of Domination to command the Tormented Amalgamation in the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59759] = { id = 59759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lion's Cage", description = "Anduin is being kept in a place the shades call the Tremaculum. It's not far, but the way is perilous.\n\nI have tried more than once to free him from his captors, but the forces holding him are too great for me to handle alone.\n\nI'm counting on your presence to tip the scales.", completion = "I knew in my heart the Light wouldn't fail us.\n\nYour presence here is the proof.", objectives = "Find King Anduin Wrynn in the Tremaculum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59760] = { id = 59760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Afflictor's Key", description = "Sylvanas thinks us broken. She believes she has already won.\n\nWe will show her how mistaken she is.\n\nFirst, I will need your help. The bonds that hold me are impossibly strong. We will need the key to free me of them.\n\nMy... imprisonment here has been overseen by a creature they call the Afflictor. The key is likely in its possession.", progress = "Did you find the key?", completion = "I had almost forgotten the feeling of freedom.\n\nNow, let us take the fight to these fiends.", objectives = "Collect the Afflictor's Key from Phael the Afflictor in the Tremaculum and unlock the Mawforged Shackles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59761] = { id = 59761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Undeserved Fate", description = "I have seen many souls brought here during my detention. The Jailer seems to want to break them, to twist them into his service... or worse.\n\nNo soul deserves such a fate, {name}.\n\nThe Mawsworn here hold the keys to their chains. Free as many as you can and we'll get them away from here.", progress = "Free those souls, {name}. They should not be bound here.", completion = "I knew I could trust you with this task. \n\nThough we face insurmountable odds, we must try to do what is right.", objectives = "Collect Mawsworn Keys from Mawsworn forces in the Tremaculum and use them to free 15 Shackled Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59762] = { id = 59762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By and Down the River", description = "Our next step is clear. We must travel to Zovaal's Cauldron--a frightful place I've heard spoken of in fanatical whispers. It's a forge of sorts that lies across the River of Souls.\n\nI have only been there a handful of times, but I have seen Baine held captive by the soldiers there. If fortune favors us, he'll still be nearby.\n\nOnce he's safe, we can see about finding this waystone the shade spoke of.", progress = "We must hurry!", completion = "The Jailer has Baine!\n\nThis is worse than we feared...", objectives = "Cross the bridge over Gorgoa, the River of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59765] = { id = 59765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wounds Beyond Flesh", description = "Even as Baine's flesh mends, his spirit draws closer to death. I have seen dark magic like this before... among the Shadowmoon clan.\n\nThe Jailer's minions must have inflicted a similar malady upon Baine. \n\nThe only cure for the Shadowmoon's curse was to find the object they used to poison the spirit and shatter it.\n\nThe sorcerers of this realm wield ornamental daggers. That might be what we're looking for.\n\nWe must find the one that they used on Baine--quickly!", progress = "We can only hope Baine's curse was inflicted by one of the sorcerers here.", completion = "We were fortunate to find the sorcerer who poisoned Baine's spirit.\n\nI will need your help breaking its link to the High Chieftain.", objectives = "Collect a Wither Blade from a Mawsworn Soulrender in Detrithos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59766] = { id = 59766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Axe", description = "I was a damned fool for throwing my axe at that sea hag. We can't afford to lose focus.\n\nThe battle ahead won't be easy. I'll need another weapon to help us fight to the waystone.\n\nLooks like these soldiers have plenty of armaments. Let's keep an eye out for one I can use.", progress = "There should be something I can use around here...", completion = "This lacks the balance and craftsmanship of a good Frostwolf axe, but it will have to do.\n\nLet's get moving.", objectives = "Find a suitable weapon for Thrall amongst the Mawsworn Armaments in Detrithos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59767] = { id = 59767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Salvation", description = "We must move quickly if we wish to find the waystone. The soul mentioned it overlooks the Cauldron, which would put it somewhere upon the ridge on the other side.\n\nUnfortunately, this area is swarming with enemy forces. We'd best avoid engaging them, lest we draw the Jailer's attention.\n\nI can shield us from sight, but we all have to stay together.", progress = "Stay close. We cannot risk being seen by the Jailer's forces.", completion = "We made it! \n\nIf we can activate this waystone, we just might be able to escape this place!", objectives = "Lead your allies past Zovaal's Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59770] = { id = 59770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand as One", description = "<Anduin examines the obelisk intently.>\n\nI've never seen markings like these before. I've studied titan artifacts, but this appears to be made by a different hand. \n\nHmm. It doesn't respond to me. I think Jaina's right. The waystone is reacting to your presence.\n\nPerhaps you'll have better luck activating it.\n\nStay on your guard. The Jailer's forces paid this no mind when it was dormant, but there's no telling what they'll do if that changes.", completion = "<The waystone appears to be waiting for something.\n\nYou reach out and touch its surface...>", objectives = "Activate the Eroded Waystone in Cocyrus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59771] = { id = 59771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "History of Corruption" }
quests[59772] = { id = 59772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Ruination", description = "The Cult of the Damned continue their work within the halls of Aldur'thar. \n\nInfiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.", progress = "Making progress?", completion = "We will see how long this postpones their efforts.", objectives = "Destroy 5 Research Notes at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59773] = { id = 59773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Ascended", description = "When you arrive in Bastion, seek out one of the kyrian. Explain that you require an audience with the Archon. Like the Arbiter, she is one of the Eternal Ones who rule over the Shadowlands.\n\nIf anyone can guide you to the truth, it is the Archon. Perhaps she will even know a way to end this anima drought.\n\nOnce you find the answers you seek, you are welcome to return to Oribos.\n\nPurpose guide your path, mortal.", completion = "The way is open again! Archon be praised!", objectives = "Journey to Bastion to inquire about the Maw kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59774] = { id = 59774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Eternity", description = "Forgive my reaction. You see, the way from Oribos has been closed for quite some time. We did not know if it would ever open again.\n\nI welcome you, noble soul, to Bastion. Your deeds in life have earned you a most glorious fate! You are to become a kyrian, a winged bearer of the dead.\n\nMy name is Kleia. It would be an honor to introduce you to our beautiful realm. There is much you must learn before your journey can begin.\n\nGather yourself. When you are ready, we will venture on.", completion = "The Greeter will soon answer all of your questions. That is its purpose, after all.\n\n<Kleia smiles at you.>\n\nI hope you are excited. I certainly am!", objectives = "Speak with Kleia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59775] = { id = 59775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Indigo find Penthia" }
quests[59776] = { id = 59776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Mouths of Madness", description = "I cannot express my gratitude enough for your help, champion. \n\nWe mustn't linger, however. The Jailer's forces will soon be alerted to the disturbance here.\n\nLet us leave this place at once!", progress = "The fiend is ready to talk. Let's get on with it.", completion = "I cannot say I enjoyed wielding the Helm of Domination. The magic it holds is... unsettling to the dead.\n\nI gladly return it to your care.", objectives = "Return to Lord Darion Mograine in Forlorn Respite and see what he has learned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59777] = { id = 59777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Calix find Amethia" }
quests[59778] = { id = 59778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Sawn find Varrik" }
quests[59779] = { id = 59779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Moriaz find Buttons" }
quests[59781] = { id = 59781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Guy", description = "You're not the first newcomer wanting to become famous. There've been a lot like you around! \n\nThe last few wanted to prove themselves by killing a giant bloodtusk... none of them ever returned! You want to get recognition?\n\nGo find all those missing newcomers and kill the bloodtusk yourself.", progress = "Did you prove yourself?", completion = "Too bad about the last few, but you're still here!", objectives = "Find 5 Newcomer Corpses and slay Deadeye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59782] = { id = 59782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathspeaker's Devout", description = "Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work.\n\nClearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments.\n\nGo forth and purge those fanatics from their camp.", completion = "My, you made quick work of them.\n\nWe will continue to monitor the area and report any cultist activity to the justicar.", objectives = "Kill 6 Dark Ritualists and 6 Dark Zealots at Deathspeaker's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59783] = { id = 59783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultist Captors", description = "Those damned cultists are relentless!\n\nThey caught us off guard and managed to drag a few of our crusaders back to their camp.\n\nLight only knows what they're doing to them up there...\n\nWord is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt.\n\nYou can find the cultists lurking up in their mountain camp.", progress = "What news have you?", completion = "Why am I not surprised? You almost make it look too easy.", objectives = "Retrieve the Interrogator's Key from Interrogator Grell. Rescue 8 Captive Aspirants at Deathspeaker's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59789] = { id = 59789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tithe and Taxes" }
quests[59800] = { id = 59800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Spirit", description = "Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on.\n\nEnter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!", completion = "Nice work firing up the combatants. They'll remember you helped them... if they survive.", objectives = "Douse 15 Arena Challengers with the Flask of Team Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59801] = { id = 59801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Power", description = "Wait! Before you enter, I would ask something of you.\n\nWhile we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm.\n\nWhatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves.\n\nKeep an eye out for any anima within the village. We will put it to better use elsewhere.", progress = "Were you able to find any anima?", completion = "May this find use in the forest. May their losses not be in vain.", objectives = "Collect 8 Animacones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59802] = { id = 59802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crumbling Village", description = "This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this?\n\nThere is only one way to be sure. Come with me to the village. Or what remains of it.", completion = "N-no... the village. They are all....", objectives = "Follow Partik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59803] = { id = 59803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Honor" }
quests[59804] = { id = 59804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gateways of Horror" }
quests[59805] = { id = 59805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw Manifested", description = "Ya heard it from Mueh'zala himself... tanks to ol' Bwonsamdi. Dere be an ancient spirit trapped in da Maw. Me bettin' da Winter Queen gonna want it back.\n\nGood ting ya been goin' down dere yaself, hm? Should be nice an' easy for ya.\n\nMe gonna clean up da rest of da undead here. Meet ol' Bwonsamdi in Ardenweald when ya get back.", completion = "All me trainin' as a shadow hunter been leadin' ta dis moment. \n\nTrackin' a spirit inside da Maw and savin' dem from eternal torture...", objectives = "Travel to the Maw to find the lost wild god of Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59808] = { id = 59808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muck It Up" }
quests[59809] = { id = 59809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On De Other Side", description = "Ay dere, {name}... It be your ol' friend, Bwonsamdi!\n\nI hear ya be workin' for da Winter Queen. Seems ya be makin' quite a name for yaself!\n\nArdenweald be in grave danger, but da Queen... well, she be too proud to deal with ol' Bwonsamdi.\n\nYa wanna save da forest, mon? Come visit me on da Other Side.\n\nI gonna be waitin' for ya...", completion = "Welcome to da Other Side!\n\nWhat ya tink, mon? Ya like what I done wit' da place?", objectives = "Use the deathstone to travel to the Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59811] = { id = 59811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Inventory", description = "Dark forces be at work, {class}. \n\nArdenweald be where loa go ta be reborn after dey die on Azeroth. But some of da loa who be sleepin' in Ardenweald have gone missin'!\n\nGotta be someone powerful behind it, takin' dem from right under da Winter Queen...\n\nOl' Bwonsamdi can't be havin' loa vanishin' from Ardenweald. Dat could be me someday! No, no... we gonna put a stop to dis!\n\nGo back ta Ardenweald and search for da missin' loa.", progress = "Dark forces be at work in Ardenweald...", completion = "So Hakkar and Dambala be da ones gone missing? Hmm... we'd better find out where dey went!", objectives = "Search the Tranquil Pools for missing loa pods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59812] = { id = 59812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Trail", description = "I got a bad feelin' about dis, mon.\n\nWildseeds don't just go missing... especially da kind wit' powerful loa in dem! Even da bad eggs like Hakkar and Dambala be protected by da Winter Queen. Someone... or someting... must be stealin' dem!\n\nBut why? Dey weren't even ready ta be reborn...\n\nSearch da area and see if ya can pick up da trail. Missing loa be bad for business... and Bwonsamdi be in enough trouble wit' da boss already!", progress = "Hakkar and Dambala both gone missin' at da same time? Oh, I got a bad feelin' about dis...", completion = "Da tracks lead into da grove up ahead. I got a feelin' Hakkar and Dambala be somewhere nearby...", objectives = "Search for clues leading to the missing loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59813] = { id = 59813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Mueh'zala", description = "Dese all be followers of Mueh'zala! Me shoulda known he be da one behind it all.\n\nMueh'zala be da loa of death from long ago. It be him who raised up Ol' Bwonsamdi, him who made me a loa.\n\nDat be before his worshippers started turnin' away from him. He always been a greedy one... but dis...\n\nMueh'zala be goin' too far dis time! We gotta stop him, or he gonna take all da loa in Ardenweald!", progress = "Mueh'zala be goin' too far dis time!", completion = "Ya did good! But dis be far from over...", objectives = "Defeat High Priest Rakazodu and 8 Mueh'zala forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59815] = { id = 59815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Loa", description = "Hakkar and Dambala be somewhere in da grove.\n\nWe need ta hurry and find out what Mueh'zala be up to. Dem two loa been mighty powerful on Azeroth... powerful and evil. Who knows what Mueh'zala be plannin' for dem!\n\nSearch da Spirit Glen. Find da missing loa and see what Mueh'zala be meanin' ta do!", progress = "We gotta know what be happenin' ta da missin' loa!", completion = "It all be makin' sense now. Mueh'zala be draining anima outta da other wildseeds so he can be wakin' Dambala and Hakkar before their time.\n\nDa Winter Queen gotta be told 'bout dis before it too late...", objectives = "Locate Hakkar the Soulflayer and Dambala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59817] = { id = 59817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winter Be Comin'", description = "Da boss be puttin' together an army of terrible loa. Hakkar and Dambala may only be da beginnin'. How da boss get so strong? I not be seein' him use power like dis before...\n\nDa Winter Queen not be fond of ol' Bwonsamdi, but we gonna need her help to stop Mueh'zala.\n\nYa be friendly wit' da Queen, no? If she be willin' to rally her forces, we might be able to stop Mueh'zala before it be too late.\n\nHead to da Heart of da Forest and speak wit' da Queen. She be our only hope now.", progress = "We gotta convince da Winter Queen to join forces against Mueh'zala...", completion = "I am not eager to do any favors for Bwonsamdi, but Mueh'zala's actions cannot be ignored.", objectives = "Gain an audience with the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59818] = { id = 59818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering The Hunt", description = "Loath as I am to aid Bwonsamdi, Mueh'zala must be made to answer for his crimes.\n\nWe will eradicate his worshippers and drive them from the forest before they cause more harm.\n\nRally the groves and muster the Wild Hunt. Ardenweald has need of its protectors.\n\nMake haste, <huntsman/huntress>.", completion = "You're just in time. The Wild Hunt is locked in battle with Mueh'zala's forces.", objectives = "Gather the Wild Hunt to Tirna Noch in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59819] = { id = 59819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Forest", description = "The Winter Queen has commanded us to drive Mueh'zala's forces out of Ardenweald.\n\nThis won't be an easy battle. The death loa's army is strong, and several of our hunters have been gravely injured.\n\nCan we count on you to turn the tide in our favor, {name}?\n\nAid our fallen allies and vanquish Mueh'zala's minions!", progress = "The fight is far from over.", completion = "The Wild Hunt can handle pushing the rest of them out of the forest. Well done, {name}!", objectives = "Aid the Wild Hunt in their fight against the forces of Mueh'zala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59821] = { id = 59821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Queen", description = "Mueh'zala's forces are routed, and it's only a matter of time before the Wild Hunt completely purges them from Ardenweald.\n\nBut something tells me that the struggle between Bwonsamdi and Mueh'zala is far from over. That creepy little mask has gone silent...\n\nYou should hurry back to the Heart of the Forest and report to the Winter Queen. She will decide what we do next.", completion = "Welcome news, indeed. I will not soon forget Mueh'zala's transgressions.", objectives = "Speak with the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59822] = { id = 59822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking a Wild God", description = "Dis be a dark place, {name}. We gotta track down da spirit who be trapped here.\n\nMe tink me can pick up its trail... but dat be all dis ol' shadow hunter can do.\n\nIf me be tryin' ta fight wit' ya, da threads dat be tyin' me ta Azeroth might break. Den I gonna be stuck here, too.\n\nC'mon. We best be moving.", completion = "We ain't done wit' dis place yet. Dere be loa trapped here!", objectives = "Track down the missing spirits of Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59824] = { id = 59824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa Rescue", description = "We be here for Ashamane, but me sensin' loa bein' tortured up ahead. Three of dem, if me be right.\n\nMe don't know who dey be, but dey don't belong in da Maw.\n\nWe need ta be bringin' dem back ta Ardenweald, too!", completion = "Rezan be needin' us!", objectives = "Find and rescue the three loa trapped within the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59825] = { id = 59825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seed Hunting" }
quests[59826] = { id = 59826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly.", objectives = "Defeat Mistress Dyrax in the Theater of Pain, when she appears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59827] = { id = 59827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Devmorta in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly.", objectives = "Defeat Devmorta in the Theater of Pain, when he appears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59828] = { id = 59828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Ti'or in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly.", objectives = "Defeat Ti'or in the Theater of Pain, when she appears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59836] = { id = 59836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battles Won Long Ago" }
quests[59837] = { id = 59837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working for the Living", description = "I see you are wondering where we acquire all of the challengers we supply to this arena.\n\nWe scour countless realms in search of opponents to provide the Maldraxxi with firsthand combat experience. \n\nCurrently, I am in the process of procuring a new combatant--and with it, a lucrative betting opportunity. \n\nWould you make use of our portal and assist Zo'umlo in capturing Khogov the Expunger? You will be appropriately compensated, of course.", progress = "Have you successfully captured Khogov the Expunger?", completion = "Competing in the arena is but one way to contribute to this venture. There are many other tasks to perform, as well.", objectives = "Shattered Grove secured and Khogov the Expunger captured.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59838] = { id = 59838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge War Machines", description = "The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority.\n\nThough they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike.\n\nPlant these charges underneath the war machines and then clear the area.", completion = "A job well done, {name}.\n\nNow our forces can advance without worrying about the enemy's weaponry.", objectives = "Destroy 5 Scourge War Machines in The Conflagration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59839] = { id = 59839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WARNING: This is Only a Test!", description = "Where some see a problem, I see an opportunity. What this Scourge fiasco calls for is a creative solution!\n\nBehold--my \"secret weapon\"!\n\nControlled by none other than my Carefully Constructed Control Device, or C.C.C.D. for short!\n\nHmm, that name might need a little work.\n\nYou're the first to see it, so that means you'll be the first to test it. But don't worry, I'm pretty sure it's safe.\n\nGood luck!", progress = "So, how's it goin'?", completion = "Oh boy! Did you see the look on their faces?\n\nI mean, some of them didn't really have faces, but you know... their jaws and whatnot. Hah!\n\nThat was great. The possibilities are endless!", objectives = "Successfully complete the testing of Fizzix Blastbolt's \"Secret Weapon\" at Deathspeaker's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59840] = { id = 59840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Divine Gratitude", description = "Many thanks for restoring my power and vigor.\n\nMy path will now lead me back to my people, but it is only right that you are rewarded for your efforts.", objectives = "Accept the boon offered by the deity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59846] = { id = 59846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finders-Keepers, Sinners-Weepers", description = "Oh hello, mortal. You have a real knack for arriving at the most opportune times. I wonder what Taskmaster Matyas wants with you. Curious.\n\nAs for me, again Matyas has used my sinstone against me. I was already enraged that he caged me and I assure you that this latest attack will not go unanswered. Yet, while he has my sinstone I am unable to act against him directly. So we must remedy that.\n\nYou question the laborers and I will read this journal while I regain my strength.", progress = "Have you discovered anything useful?", completion = "Ah. A pity none of these are mine. Still they may prove useful.", objectives = "Discover the secrets of Taskmaster Matyas's efforts in Feeder's Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59847] = { id = 59847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Rampart", description = "The Scourge are assaulting our outpost! We must defend it at all costs!\n\nSlay as many of the fiends as you can!", objectives = "Defend against the Scourge attack atop the Ironwall Rampart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59848] = { id = 59848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Tales: Theotar" }
quests[59850] = { id = 59850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Tales: Vulca" }
quests[59851] = { id = 59851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen Solid", description = "The breath of a frost wyrm can freeze even its largest foes in an instant. Our forces, unfortunately, have experienced this firsthand.\n\nTheir advance toward the citadel has come to a halt. I fear we may lose our foothold unless we act quickly.\n\nTake this potion and use it to free our forces from their frigid bonds. Light be with you.", progress = "Always keep an eye to the sky.", completion = "Excellent work, {name}. We will see to it they recover in safety.", objectives = "Rescue 12 Frozen Allies at the Court of Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59852] = { id = 59852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Tales: Gubbins and Tubbins" }
quests[59853] = { id = 59853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea Tales: Lost Sybille" }
quests[59855] = { id = 59855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Mirror Disruptions" }
quests[59856] = { id = 59856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezan, Loa of Kings", description = "Rezan be a powerful loa, one of great importance ta da Zandalari.\n\nWe need ta rescue him... but dis creature be projectin' a barrier of death. Notin' be gettin' in.\n\nUnless... I be usin' me own anima ta shield ya from its magic.\n\nYa gotta act fast and kill da monster dat be drainin' Rezan. Me anima not gonna last forever.\n\nSay da word when ya ready ta go.", progress = "We need ta save Rezan!", completion = "Me be feelin' Rezan's essence inside of me... he be trustin' me wit' a great gift.\n\nNo matter what be comin' next, me not gonna let him down.", objectives = "Accept some of Vol'jin's anima to protect yourself, then slay Exhaurbius to save Rezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59862] = { id = 59862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savior for Lost Souls", description = "The forest sighs in greeting, Maw Walker.\n\nYour arrival was written in the stars, and awaited by the boughs. Now our work begins. \n\nLet us proceed.\n\nFollow this path into the grove.\n\nThese are but the first steps on our journey together.", progress = "Our paths converge. Together we walk.", completion = "Your presence warms the grove.\n\nNow we learn, and grow.", objectives = "Walk with the Warden to the grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59863] = { id = 59863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Nullifier 07-X", description = "While everyone is busy fending off our enemies with swords and magic, how about we try something different.\n\nBehold, my latest invention--the Combat Nullifier 07-X!\n\nWith this device, no enemy is truly your enemy any longer!\n\nNow, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly.\n\nFor now, we'll need to \"borrow\" some energy from our enemies in order to operate it.\n\nGo ahead. Charge it up and give it a whirl!", progress = "How's it going?", completion = "Whoa! That was a blast, huh?", objectives = "Charge the Power Containment Module to Blast 5 enemies with the Combat Nullifier 07-X at Sindragosa's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59865] = { id = 59865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerflight", description = "This so exciting!\n\nCome, another test is in order. I can hardly wait!", completion = "I did it! I flew!\n\nI have adjustments I can make. Here, take these glimmerflies as thanks. I will collect more!", objectives = "Observe Kowalskos' test flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59866] = { id = 59866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Ways", description = "Me don't know what fate be comin' for ol' Vol'jin... but it be waitin' for me in Ardenweald.\n\nAshamane, Hir'eek, Shadra... dey belong dere, too.\n\nWe best be gettin' outta here. Me had enough of da Maw for an eternity.", completion = "It fills me with joy to know that the spirits lost to the Maw are safe once more.\n\nNone can say what fate has in store for Vol'jin. The path on which he has embarked has never before been walked by a mortal soul.\n\nYet whatever awaits him, know that your efforts are what made it possible.", objectives = "Return the lost loa and Vol'jin to the Winter Queen in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59867] = { id = 59867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Appraiser Vix", description = "For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix.\n\nSpecial warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders.\n\nElimination of this felon is of the highest priority.", progress = "Eliminate Appraiser Vix.", completion = "Excellent work, Maw Walker. I shall dispatch Zo'umlo to retrieve our stolen property.", objectives = "Eliminate Appraiser Vix", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59868] = { id = 59868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offer of Freedom", description = "Just as I was, some of the Briarbane venthyr you encounter will have been compelled to serve Matyas. They likely will not want to fight you, but will have no choice. Once they are injured, they may be willing to pause to see if one of the sinstones you recovered earlier is theirs.\n\nFree those you can. The use of a sinstone to compel others isn't fair.", progress = "Have you released the compelled venthyr?", completion = "You've made some friends today.", objectives = "Weaken Briarbane venthyr and then offer them a sinstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59871] = { id = 59871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catalyze This", description = "The grove grows in power, and so shall the spirits it shelters.\n\nYou have nurtured a spirit to rebirth on your own. Now you must learn to make use of catalysts.\n\nWhen planted near a wildseed, catalysts grant the slumbering spirit strength beyond what it knew in life. Strength that it retains when reborn.\n\nCatalysts are special and rare, though I have one here for you to use. Others can be found across the Shadowlands.\n\nFor now, plant the catalyst and witness the potential it holds.", completion = "Nature holds as many secrets as it does gifts.", objectives = "Use the catalyst on the catalyst plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59872] = { id = 59872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Save a God", description = "Many mortal souls suffer within the Maw. But so too do many spirits of Nature.\n\nAnima alone cannot heal wounds inflicted by the Jailer. Spirits plucked from his grasp must be planted anew and tended with care.\n\nThese wildseeds are unlike any other. This grove, unlike any other. Within them lies dormant hope, a chance for even the weakest spirit to be reborn.\n\nOne such as this. Lay this spirit to rest within a wildseed. Let its rebirth begin.", progress = "Let fate and compassion guide your hand.", completion = "Your skills take root, Maw Walker.", objectives = "Place the Soul Seed into the wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59873] = { id = 59873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greeting a God", description = "Soon, the moment of the spirit's rebirth will be nigh. A fate all but extinguished by the Maw, rekindled by grove and caretaker.\n\nTime will be the spirit's salve. Once enough of it has passed, lay your hands upon the wildseed and awaken them.", progress = "Patience is the way of the forest.", completion = "And so a god is reborn by the hand of a mortal.\n\nThey greeted you with gratitude, yes? And perhaps surprise, as well.", objectives = "Wait for the spirit to finish incubating, then open the wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59874] = { id = 59874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw", completion = "What news from Maldraxxus, {name}?", objectives = "Speak with Bolvar in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59876] = { id = 59876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Reports", description = "The Scourge can strike anytime, anywhere.\n\nTo counter their unpredictability, the Argent Crusade has secured key locations along the southern road heading east. However, I have yet to receive any reports from our scouts in the field.\n\nWith the erratic nature of these attacks, I fear the worst.\n\nTravel the road and take stock of our outposts. I'll be expecting a full report when you return.\n\nLight be with you, {name}.", progress = "Gregor sent you?", completion = "This is far worse than we thought.\n\nCommander Gregor must be told of the true extent of the Scourge's resurgence.", objectives = "Gather reports from officers in Elwynn Forest, Redridge Mountains and Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59877] = { id = 59877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message from Icecrown", description = "We received word from our forces in Northrend. Justicar Trueheart requests our immediate assistance.\n\nAs you are an experienced {class}, I ask that you answer the call.\n\nThe urgency of this summons cannot be ignored, even if it means braving the terrors of Icecrown itself.\n\nI know you fear for the safety of everyone here. I will continue to coordinate our efforts and call in additional reinforcements.\n\nLight be with you, {name}.", completion = "You arrive just in time. Commander Gregor spoke highly of you.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59878] = { id = 59878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Many Whelps", description = "We cannot hope to hold this ground if frostwyrms strafe the skies above us.\n\nCultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces.\n\nPut an end to their efforts.", completion = "A job well done, {name}. That should grant us a brief respite.", objectives = "Kill 4 Wyrm Reanimators and 12 Frostbrood Whelps at Sindragosa's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59879] = { id = 59879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Thing of Ours", description = "Au'narim is the top broker here. She keeps this place supplied with exotic creatures for us to fight in the arena. \n\nShe's noticed your efforts and wants to meet you!\n\nThis is important. A broker's backing could lead to an invitation to compete!", completion = "You must be one of these outsiders I hear so much about.", objectives = "Meet with Au'narim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59882] = { id = 59882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sure Bet", description = "You appear to have great profit potential.\n\nThere are many interested parties willing to bet upon your performance in the Theater of Pain.\n\nGo now, Louison will arrange your appearance.", sourceObjective = "Meet with Louison", sourceObjectiveStatus = "unverified-source-field" }
quests[59894] = { id = 59894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golden Dawn", description = "The machinations of war commence. Gharmal's crimes are now evident to all of the Shadowlands.\n\nBastion demands vengeance, and we shall share it with them. Only our combined forces will defeat the Constructs once and for all.\n\nMeet Draka at the overlook. Your presence there will help solidify an agreement.", completion = "An alliance is secured. Now we plan the attack.", objectives = "Teleport to the Overlook to meet with Draka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59897] = { id = 59897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Baron", description = "Take this amulet. One like it is carried by each of the Four Horsemen.\n\nThe amulets are imbued with a power that links them to one another. That connection should help you locate Darion Mograine.\n\nNo doubt Darion has witnessed countless horrors in the Maw. Perhaps he has caught sight of the missing baron.\n\nLet us hope he can lead you to our Azerothian allies as well.", objectives = "Enter the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59902] = { id = 59902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Cache" }
quests[59903] = { id = 59903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Split Blob Test" }
quests[59904] = { id = 59904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Cache" }
quests[59905] = { id = 59905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Cache" }
quests[59907] = { id = 59907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mawsworn Menace", description = "Our knights are strong, but they don't stand much chance scattered against such an opponent.\n\nWe need to thin the ranks of our foe. The Ebon Blade won't do us any good if they are cut down.", progress = "Let your blade do the talking!", completion = "Our enemy is relentless, but we will continue to drive them back.\n\nStand vigilant, {class}.", objectives = "Defeat 8 Mawsworn enemies in the Crucible of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59910] = { id = 59910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight and Flight", description = "Mograine and Emeni will lead the assault on the western gate. \n\nYou and Xandria will advance from the east. Secure the area and slay all who oppose you. \n\nOnce we have them surrounded, we can strike the final blow against Gharmal.", completion = "This place is mired with atrocities. They must be purged.", objectives = "Fly with Xandria to the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59914] = { id = 59914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear to Tread", description = "It appears we've escaped our enemies' notice for the moment. We should take the opportunity to scout the nearby area for signs of our allies.\n\nWe will draw less attention alone. The Ebon Blade will hold back, awaiting my signal.\n\nCome, let us see what awaits us in this hellscape.", progress = "Champion? Tell me this is not an illusion.", completion = "Praise the Light! I... I'd almost given up hope.\n\n<Jaina looks upon the Ebon Blade knights.> \n\nIs this... all that remains of your forces?", objectives = "Scout Calcis for any signs of your allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59915] = { id = 59915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul in Hand", description = "My instincts were correct. Whatever dark magic binds these souls together also keeps them more or less coherent.\n\nIt will take time, but we will find out what this thing knows. My interrogation will require use of the helm, but rest assured I will return it to your care.\n\nLet's bring our prize to the Lord Admiral.", sourceObjective = "Return to Lady Jaina Proudmoore in Forlorn Respite.", completion = "It seems your search was a success.\n\nEnough rest. There's much to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[59916] = { id = 59916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butchers of Bastion", description = "Did these fiends show my kin mercy when they attacked Bastion? When they tore my brothers and sisters limb from limb and used them to create more of these... these monstrosities?!\n\nNo! The butchers of Bastion made clear their hearts that day!\n\nThey deserve only the eternal darkness that awaits them. Ensure that they meet it!", completion = "This bloodshed will not bring them back... but it may spare others from the same fate.", objectives = "Kill 10 House of Constructs forces in the Separation Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59917] = { id = 59917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Them, Of Course", description = "These mindless monstrosities hail from the farthest reaches of the Shadowlands. The anima drought has fueled their relentless hunger, driving them to seek new sources.\n\nTheir presence here is inconvenient, to put it mildly.\n\nThey tear at the land searching for any anima they can find. We must thin their numbers and buy time to safeguard the knowledge locked within the Sepulcher.\n\nExactly the sort of work you're accustomed to, yes?", progress = "How did the hunting go?", completion = "Nicely done. You've bought us precious time.", objectives = "Slay 8 Enraged Gluttons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59919] = { id = 59919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earned Bond", description = "There is one more thing you should do, Maw Walker.\n\nIn rebuilding the Crest of Ascension you have earned more than just the trust of your fellow kyrian. It would seem our Forgelite Prime, Mikanikos, has rather enjoyed your time together and would like to soulbind with you.\n\nGiven his predilection towards, well, himself, I am as surprised as you are. You must have truly impressed him.", progress = "This is a moment to remember.", completion = "Never in all my millennia did I think I would see the day a steward would soulbind with an outsider. Times are certainly changing, are they not?", objectives = "Soulbind with Mikanikos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59920] = { id = 59920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light the Forge, Forgelite", description = "I think we have the materials I will need to light the forge, at long last.\n\nI am afraid the place is in a state of disrepair. Between failed attempts at working without anima and simple neglect, I cannot hope to work the forge as it currently stands.\n\nI would very much appreciate your help to get the place in order while I coax the forge to life once more.", completion = "I am deeply grateful for your help. Now I can practice my craft again!", objectives = "Help Forgelite Sophone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59921] = { id = 59921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All I Ever Will Be", description = "This is the site of an ancient battle won by the previous Paragon of Courage. She sacrificed herself to serve the Shadowlands. I only hope my own end will prove as exemplary.\n\nMany of my disciples meditate upon the scrolls here. With them, we remember the foundation of our courage.\n\nAccompany Alexandros as he reflects on his shrines. Aid him in understanding where the source of his courage lies.\n\nHe will learn that this afterlife is not the one suited for him.", progress = "What have you learned?", completion = "Did this venture enlighten you?", objectives = "Reflect on the Scrolls of Remembrance with Alexandros Mograine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59922] = { id = 59922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Not Forget", description = "The Arbiter's judgment was, as always, infallible.\n\nThough Alexandros's devotion to the Light is undeniable, it is the memory of his loved ones that truly fuels his strength. He was meant for Maldraxxus, not Bastion.\n\nNonetheless, our reclamation of the temple stands. My vengeance is not yet complete, but now I know that some of the Maldraxxi can still be trusted.\n\nGo now. Return to your leader with news of our victory today.\n\nAnd tomorrow, we shall purge our foes once and for all.", completion = "So we have proven our honor... and gained a new ally.", objectives = "Return to Draka in the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59926] = { id = 59926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warming Up", description = "We're nearing the island where the Horde's last expedition was lost. \n\nYou need to be prepared for what's out there. Warm up on these combat dummies.", progress = "Do not bother me! Go and attack those combat dummies. Show me your power.", completion = "Good, you've kept training since we set sail.\n\nI need to speak with the crew about this storm. \n\nSpar with Throg. He will assess your skills and decide on your role once we make landfall.", objectives = "Warm up by fighting a Combat Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59927] = { id = 59927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stand Your Ground", description = "Lok-tar! Nothing quite like a good fight in the rain. \n\nWe will spar together and take the measure of your strength!", completion = "You show promise, {class}. Perhaps you too will find glory on the island!", objectives = "Spar with Grunt Throg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59928] = { id = 59928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brace for Impact", description = "Well fought, {name}. You bring strength and honor to the Horde!\n\nNow we just--wait...\n\nDo you hear that?", sourceObjective = "Find Thrall.", completion = "This ship won't make it to the island in one piece.\n\nHold on to something, and pray that the elements will spare us from a grim death at sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[59929] = { id = 59929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Mania", description = "The shore is littered with shipwrecks. This must be where the lost expedition crashed.\n\nWe'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up.\n\nSlay those murlocs to get back what belongs to the Horde.", progress = "The murlocs are carrying our first aid kits. Slay them and bring all of the kits to me.", completion = "Excellent work. Let's get the survivors back on their feet.", objectives = "Recover 6 First Aid Kits from Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59930] = { id = 59930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency First Aid", description = "We must treat our wounded before we can begin for the missing expedition.\n\nTake this first aid kit and tend to the survivors. I'll handle the others nearby.", progress = "Use your first aid kit to help the others.", completion = "We're back on our feet. Now let's move. The lost expedition is somewhere on this island.", objectives = "Use a First Aid Kit on Bo, Mithdran Dawntracker, and Lana Jordan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59931] = { id = 59931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Lost Expedition", description = "Breka Grimaxe went north to look for survivors. Join her to see what she's found.\n\nI'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.", completion = "So... hungry...\n\nDey took... everyone else... I be... da last one...", objectives = "Search the nearby camp for expedition survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59932] = { id = 59932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking Meat", description = "This is Won'sa, a shaman who was with the expedition.\n\nShe is dying of starvation. A death unfit for the Horde!\n\nSlay some of the nearby wildlife for their meat and cook it over the fire.\n\nWon'sa can tell us what happened to the missing expedition after she eats.", progress = "Please... I be needin'... food...", completion = "<Won'sa quickly eats the meat that you cooked.>\n\nLooks I not gonna be knockin' on Bwonsamdi's door, after all.\n\nYa best hurry. Da quilboar took Shuja and da rest of da expedition!", objectives = "Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59933] = { id = 59933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", completion = "You're ready to slaughter the quilboar! Let's speak to Won'sa and see what she knows.", objectives = "Spar with Warlord Grimaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59934] = { id = 59934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhanced Combat Tactics", description = "Won'sa said the quilboar have kidnapped the missing expedition... including my daughter.\n\nThe quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs.\n\nI won't see you die by their hands. We're going to spar one last time.\n\nWhen we are done, you will cleave a path straight through the quilboar!", completion = "You're ready to slaughter the quilboar! Let's speak to Won'sa and see what she knows.", objectives = "Spar with Warlord Grimaxe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
